  ('first-tax-return', 'Filing Your First Return', 'Step by step, start to submitted.', '🚀', 'taxes', 4),
  ('deadlines-and-penalties', 'Deadlines & Penalties', 'When to file and what late filing costs.', '⏰', 'taxes', 5),
  ('credits-and-benefits', 'Credits & Benefits', 'Money that can come back to you.', '🎁', 'taxes', 6),
  ('employment-and-gig-income', 'Employment & Gig Income', 'Tips, side gigs and self-employment.', '🛴', 'taxes', 7),
  ('saving-and-investing', 'Saving & Investing', 'Emergency funds and letting money grow.', '🌱', 'saving', 8),
  ('tfsa-and-rrsp', 'TFSA & RRSP', 'Two accounts with opposite superpowers.', '🏦', 'investing', 9),
