  ('quiz-module-9', 'fhsa-rrsp-and-big-goals-quiz', 'FHSA, RRSP and Big Goals', 'Module 9 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'tfsa-and-rrsp', '["q-module-9-1","q-module-9-2","q-module-9-3","q-module-9-4","q-module-9-5"]'::jsonb, null, 4, 29, true),
  ('quiz-module-10', 'moving-out-for-school-quiz', 'Moving Out for School', 'Module 10 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'slips-and-documents', '["q-module-10-1","q-module-10-2","q-module-10-3","q-module-10-4","q-module-10-5"]'::jsonb, null, 4, 30, true),
  ('quiz-module-11', 'cra-scams-deadlines-and-mistakes-quiz', 'CRA Scams, Deadlines and Mistakes', 'Module 11 · Five questions with explanations. Read the lesson, then test your understanding.', 'school-outline', 'topic', 'deadlines-and-penalties', '["q-module-11-1","q-module-11-2","q-module-11-3","q-module-11-4","q-module-11-5"]'::jsonb, null, 4, 31, true),
  ('quiz-myth-busters', 'myth-busters', 'Myth Busters', 'Ten true-or-false tax myths. Find the catch, then learn why.', 'bulb-outline', 'topic', null, '["q-myth-1","q-myth-2","q-myth-3","q-myth-4","q-myth-5","q-myth-6","q-myth-7","q-myth-8","q-myth-9","q-myth-10"]'::jsonb, null, 4, 32, true),
  ('quiz-weekly', 'quiz-of-the-week', 'Quiz of the Week', 'A fresh ten-question mix. New set every week.', '⚡', 'weekly', null, null, null, 5, 0, true),
  ('quiz-tax-basics', 'the-basics', 'The Basics', 'Who files, why, and how refunds work.', '🧾', 'topic', 'tax-basics', null, null, 4, 1, true),
  ('quiz-your-paycheque', 'your-paycheque', 'Your Paycheque', 'Gross, net, CPP and EI.', '💵', 'topic', 'your-paycheque', null, null, 4, 2, true),
  ('quiz-slips', 'slips-and-documents', 'Slips & Documents', 'T4, T4A, T5, T2202 and the TD1.', '📄', 'topic', 'slips-and-documents', null, null, 4, 3, true),
  ('quiz-deadlines', 'deadlines-and-penalties', 'Deadlines & Penalties', 'When to file and what happens if you''re late.', '⏰', 'topic', 'deadlines-and-penalties', null, null, 4, 4, true),
  ('quiz-benefits', 'credits-and-benefits', 'Credits & Benefits', 'CGEB (formerly GST/HST credit), free help, and payments.', '🎁', 'topic', 'credits-and-benefits', null, null, 4, 5, true),
  ('quiz-saving', 'saving-and-growing', 'Saving & Growing', 'TFSA vs RRSP made simple.', '🌱', 'topic', 'tfsa-and-rrsp', null, null, 4, 6, true),
  ('quiz-banking-credit', 'banking-and-credit', 'Banking & Credit', 'Cards, interest, scores and cushions.', '💳', 'topic', 'banking-and-credit', null, null, 4, 7, true),
  ('quiz-challenge-all', 'knowledge-challenge', 'Knowledge Challenge', 'Every question in the bank. How much really stuck?', '🏆', 'challenge', null, null, null, 3, 8, true)
insert into public.content_questions (id, category_id, prompt, options, answer_index, explanation, teaches_lesson_id, difficulty, published) values
  ('q-module-5-1', 'your-paycheque', 'You worked 20 hours at $17.85. Your stub shows gross pay of $357 and a deposit of $331. What is your net pay?', '["$357","$331","$26"]'::jsonb, 1, 'Net pay is $331. The $26 difference is deductions; read the stub to identify which deductions apply.', 'lesson-module-5', 'easy', true),
  ('q-module-5-2', 'your-paycheque', 'You are 16 with a part-time job. Which deduction should NOT appear on your stub?', '["EI","Income tax","CPP"]'::jsonb, 2, 'CPP generally starts the month after age 18. Ask payroll to correct mistaken deductions; any remaining overpayment can be reconciled when filing.', 'lesson-module-5', 'medium', true),
  ('q-module-5-3', 'your-paycheque', 'True or false: EI is only deducted once you earn over $3,500 a year.', '["True","False"]'::jsonb, 1, 'That $3,500 exemption is for CPP. EI comes off from the first dollar you earn.', 'lesson-module-5', 'medium', true),
  ('q-module-5-4', 'your-paycheque', 'What is the TD1 form for?', '["Filing your tax return","Telling your employer how much tax to withhold","Applying for EI"]'::jsonb, 1, 'It sets your withholding. Most students just claim the basic personal amount.', 'lesson-module-5', 'medium', true),
  ('q-module-5-5', 'your-paycheque', 'Jordan has two jobs at the same time, total income exceeds his basic personal amount, and he claims that amount on both TD1 forms. What risk does this create?', '["A bigger refund","He owes money","Nothing changes"]'::jsonb, 1, 'Both employers may withhold too little tax. A balance may be owing; the final result depends on total income, deductions and credits.', 'lesson-module-5', 'hard', true),
  ('q-module-6-1', 'tax-basics', 'True or false: if your income crosses into a higher bracket, all your income is taxed at the higher rate.', '["True","False"]'::jsonb, 1, 'Only the dollars above the line get the higher rate.', 'lesson-module-6', 'easy', true),
  ('q-module-6-2', 'tax-basics', 'Which rate tells you how much tax you will pay on one extra hour of work?', '["Average rate","Marginal rate","Basic rate"]'::jsonb, 1, 'The marginal rate applies to your next dollar earned.', 'lesson-module-6', 'medium', true),
  ('q-module-6-3', 'tax-basics', 'For a full-year Canadian resident entitled to the maximum 2026 federal basic personal amount, about how much taxable income can that credit offset?', '["$5,000","$16,452","$58,523"]'::jsonb, 1, 'The maximum 2026 federal basic personal amount is $16,452. This is a non-refundable federal credit, not an exemption from payroll deductions or provincial tax; special and high-income rules apply.', 'lesson-module-6', 'medium', true),
  ('q-module-6-4', 'tax-basics', 'In a simple 2026 federal bracket calculation, some income is taxed at 14% and the next dollar at 20.5%. Compared with 20.5%, is the average rate higher, lower or the same?', '["Higher","Always exactly the same","Lower in this simple bracket example"]'::jsonb, 2, 'Lower: part of the income is taxed in the lower bracket. Credits can reduce the effective rate further.', 'lesson-module-6', 'medium', true),
  ('q-module-6-5', 'tax-basics', 'Assuming identical total taxable income, deductions and credits, who owes more final federal income tax: one $60,000 job or two $30,000 jobs?', '["The person with one job","The same, with identical deductions and credits","The person with two jobs"]'::jsonb, 1, 'The final federal income tax is the same under those assumptions. Payroll withholding may differ.', 'lesson-module-6', 'hard', true),
  ('q-module-7-1', 'employment-and-gig-income', 'True or false: tips from a restaurant job are tax-free.', '["True","False"]'::jsonb, 1, 'Tips are income and must be reported, whether cash or card.', 'lesson-module-7', 'easy', true),
  ('q-module-7-2', 'employment-and-gig-income', 'Your jewelry business has $4,000 of revenue and $1,000 of eligible material expenses. What is the net profit?', '["$4,000","$3,000","$0, it is a hobby"]'::jsonb, 1, 'Net profit is $3,000. On the business statement, report both the $4,000 gross revenue and the $1,000 eligible expenses.', 'lesson-module-7', 'medium', true),
  ('q-module-7-3', 'employment-and-gig-income', 'A brand sends you a free $300 hoodie in exchange for a TikTok post. Is that taxable?', '["No, because no cash changed hands","Only if the hoodie is sold later","Yes, its fair market value is business income"]'::jsonb, 2, 'Yes. Products received in exchange for promotion count as income at their fair value.', 'lesson-module-7', 'medium', true),
  ('q-module-7-4', 'employment-and-gig-income', 'You sell your own old clothes on Vinted for less than you paid. Do you owe tax?', '["Only if payment is by e-transfer","Generally no taxable gain on ordinary used clothes sold at a loss","Yes, tax is due on every personal sale"]'::jsonb, 1, 'No. Selling personal items at a loss is not income. Buying items to resell for profit is a business.', 'lesson-module-7', 'medium', true),
  ('q-module-7-5', 'employment-and-gig-income', 'A self-employed 20-year-old nets $15,000. Why is her CPP higher than a regular employee''s on the same income?', '["She pays both employee and employer CPP shares","She pays a special under-25 tax","Her clients pay her CPP automatically"]'::jsonb, 0, 'She pays both the employee and employer shares of CPP, since she is her own boss.', 'lesson-module-7', 'hard', true),
  ('q-module-8-1', 'credits-and-benefits', 'True or false: if you earned under the basic personal amount, there is no reason to file.', '["True","False"]'::jsonb, 1, 'Filing can get back withheld tax and unlock benefits like the GST/HST credit.', 'lesson-module-8', 'easy', true),
  ('q-module-8-2', 'credits-and-benefits', 'Your only insurable earnings for the year were $1,800 at a daycare and EI was deducted. What happens when you file?', '["The EI premiums are never refundable","Only half is refunded","The EI premiums are refunded if total insurable earnings were $2,000 or less"]'::jsonb, 2, 'Your EI premiums come back, since your insurable earnings were $2,000 or less.', 'lesson-module-8', 'medium', true),
  ('q-module-8-3', 'credits-and-benefits', 'At what age does CGEB eligibility generally begin for a Canadian resident who has no spouse or common-law partner and is not a parent living with their child?', '["16","18","19"]'::jsonb, 2, 'Generally 19. File the year before you turn 19 so the CRA can assess eligibility. CGEB replaced the GST/HST credit in July 2026; eligibility and income tests still apply.', 'lesson-module-8', 'medium', true),
  ('q-module-8-4', 'credits-and-benefits', 'Is the Canada Groceries and Essentials Benefit (formerly GST/HST credit) taxable income?', '["No, it is a tax-free benefit","Yes, it is employment income","Only if it is paid quarterly"]'::jsonb, 0, 'No. It is a tax-free benefit, not taxable income.', 'lesson-module-8', 'medium', true),
  ('q-module-8-5', 'credits-and-benefits', 'Priya is 17 and CPP was deducted by mistake. If payroll has not reimbursed the overpayment, how can it be reconciled?', '["Ask her employer for cash","File a tax return","She cannot"]'::jsonb, 1, 'File a tax return to reconcile any remaining CPP overpayment. Asking payroll to correct the deduction is also appropriate.', 'lesson-module-8', 'hard', true),
  ('q-module-9-1', 'tfsa-and-rrsp', 'What does FHSA stand for?', '["Federal Housing Support Allowance","Flexible Home Spending Account","First Home Savings Account"]'::jsonb, 2, 'First Home Savings Account.', 'lesson-module-9', 'easy', true),
  ('q-module-9-2', 'tfsa-and-rrsp', 'You earned $10,000 last year. Ignoring pension adjustments and other adjustments, how much new RRSP room does the 18% rule produce?', '["$1,000","$1,800","$7,000"]'::jsonb, 1, '18% of $10,000 is $1,800. Annual limits and pension adjustments can affect actual room; verify the amount with CRA.', 'lesson-module-9', 'medium', true),
  ('q-module-9-3', 'tfsa-and-rrsp', 'True or false: you build FHSA room every year from age 18, even if you never open one.', '["True","False"]'::jsonb, 1, 'FHSA room starts in the year you open your first FHSA, not automatically at 18. Opening also starts the maximum participation period; check eligibility and timing before opening.', 'lesson-module-9', 'medium', true),
  ('q-module-9-4', 'tfsa-and-rrsp', 'You opened an FHSA last year but put nothing in. What is the most you can contribute this year?', '["$8,000","$40,000","$16,000, assuming no contributions or transfers and no other adjustments"]'::jsonb, 2, '$16,000. Up to $8,000 of unused room carries forward, on top of this year''s $8,000.', 'lesson-module-9', 'hard', true),
  ('q-module-9-5', 'tfsa-and-rrsp', 'You live in BC and just turned 18. Can you open a TFSA?', '["Not until age 21","Not yet: BC generally requires age 19 to open it","Yes: every province allows opening at 18"]'::jsonb, 1, 'In BC, the legal age to open a TFSA is generally 19. Eligible Canadian residents begin accumulating TFSA contribution room at 18.', 'lesson-module-9', 'hard', true),
  ('q-module-10-1', 'slips-and-documents', 'Which slip shows the tuition you paid for the year?', '["T4","T2202","T5"]'::jsonb, 1, 'Your school posts the T2202, usually in your student portal.', 'lesson-module-10', 'easy', true),
  ('q-module-10-2', 'slips-and-documents', 'True or false: unused tuition credits disappear if you do not use them that year.', '["True","False"]'::jsonb, 1, 'They carry forward with no expiry, so you can use them once you are earning more.', 'lesson-module-10', 'medium', true),
  ('q-module-10-3', 'slips-and-documents', 'You received a $3,000 entrance scholarship connected to a qualifying full-time post-secondary program. How should you handle it?', '["Include the full $3,000 as taxable income automatically","Treat it as employment income","Enter the slip and apply the scholarship exemption; only a taxable portion goes on line 13010"]'::jsonb, 2, 'Apply the scholarship exemption correctly. A fully exempt scholarship is not reported as taxable income on line 13010; tax software may ask you to enter the T4A first.', 'lesson-module-10', 'medium', true),
  ('q-module-10-4', 'slips-and-documents', 'You move from Kelowna to Vancouver for full-time university. When could moving expenses be deductible?', '["Never, because students cannot deduct moving expenses","Only if the qualifying move and eligible-income rules are met","Always, because any university move qualifies"]'::jsonb, 1, 'The new home must generally be at least 40 km closer to the qualifying school or new work location. A student move is limited to eligible taxable scholarship or similar income; a qualifying work move has its own rules. Simply taking a nearby job does not automatically qualify the move.', 'lesson-module-10', 'hard', true),
  ('q-module-10-5', 'slips-and-documents', 'Your parents'' RESP pays you $6,000, made up of $4,000 they contributed and $2,000 of growth and grants. How much counts as your income?', '["$2,000 of growth and grants","$6,000","$4,000 of original contributions"]'::jsonb, 0, '$2,000. Your parents'' own contributions come back tax-free. Only the growth and grants are taxed in your hands.', 'lesson-module-10', 'hard', true),
  ('q-module-11-1', 'deadlines-and-penalties', 'A caller says you owe the CRA $1,200 and must pay in Apple gift cards today or be arrested. What is this?', '["A scam: hang up and check through official CRA channels","A valid CRA payment request","A legitimate discount offer"]'::jsonb, 0, 'A scam. Hang up and check your balance yourself in CRA My Account.', 'lesson-module-11', 'easy', true),
  ('q-module-11-2', 'deadlines-and-penalties', 'True or false: the standard individual late-filing penalty for a balance owing does not apply when your return instead results in a refund.', '["True","False"]'::jsonb, 0, 'True for that penalty. File promptly anyway: refunds and benefits can be delayed, and other reporting obligations can carry separate penalties.', 'lesson-module-11', 'medium', true),
  ('q-module-11-3', 'deadlines-and-penalties', 'Under the standard first-time late-filing rule, you owe $500 and file three full months late. What is the penalty before interest?', '["$25","$40","$65"]'::jsonb, 1, '5% of $500 is $25, plus $15 for three full months: $40. Interest is separate; repeat late-filing rules can be higher.', 'lesson-module-11', 'medium', true),
  ('q-module-11-4', 'deadlines-and-penalties', 'A self-employed creator files on June 10 and pays her $800 balance that day. Did she do anything wrong?', '["She filed on time but may owe late-payment interest","Both filing and payment were on time","She must file a duplicate return"]'::jsonb, 0, 'Partly. Filing by June 15 is on time, but payment was due April 30, so she owes interest on the $800.', 'lesson-module-11', 'hard', true),
  ('q-module-11-5', 'deadlines-and-penalties', 'After receiving your Notice of Assessment, you spot a mistake on your return. What should you do?', '["File a second return","Request a change in My Account","Wait for the CRA to notice"]'::jsonb, 1, 'Request an adjustment using Change my return, eligible ReFILE software, or Form T1-ADJ. Wait for the assessment and do not submit a duplicate return.', 'lesson-module-11', 'hard', true),
  ('q-myth-1', 'tax-basics', 'Lottery winnings are generally taxable income for a casual lottery player in Canada.', '["True","False"]'::jsonb, 1, 'Lottery winnings are generally not taxable. Income later earned by investing the winnings can be taxable.', 'lesson-module-6', 'medium', true),
  ('q-myth-2', 'tax-basics', 'A personal $500 birthday cash gift from your parents counts as taxable income.', '["True","False"]'::jsonb, 1, 'A genuine personal cash gift is generally not taxable to the recipient. Payment for work is different.', 'lesson-module-6', 'medium', true),
  ('q-myth-3', 'credits-and-benefits', 'A large tax refund is automatically a bonus from the government.', '["True","False"]'::jsonb, 1, 'A refund may reflect overpaid tax and/or refundable credits. It is not an automatic bonus; look at the assessment to see why it arose.', 'lesson-module-8', 'medium', true),
  ('q-myth-4', 'first-tax-return', 'You must be 18 to file an income tax return.', '["True","False"]'::jsonb, 1, 'There is no minimum filing age. Reporting earned income can establish future RRSP room.', 'lesson-module-8', 'medium', true),
  ('q-myth-5', 'first-tax-return', 'You must pay a professional to prepare every tax return.', '["True","False"]'::jsonb, 1, 'Free certified software exists, and eligible people with modest income and a simple tax situation can use volunteer clinics.', 'lesson-module-8', 'medium', true),
  ('q-myth-6', 'tfsa-and-rrsp', 'A TFSA withdrawal permanently removes that amount from your contribution room.', '["True","False"]'::jsonb, 1, 'Withdrawals are generally added back on January 1 of the following calendar year. Replacing them earlier without other room can cause an overcontribution.', 'lesson-module-9', 'medium', true),
  ('q-myth-7', 'saving-and-investing', 'Interest from an ordinary non-registered savings account is tax-free.', '["True","False"]'::jsonb, 1, 'Interest is generally taxable even if no T5 is issued. Registered accounts have distinct rules; TFSA and FHSA are not the only tax-advantaged plans.', 'lesson-module-9', 'medium', true),
  ('q-myth-8', 'saving-and-investing', 'Crypto can trigger tax only when it is exchanged for dollars.', '["True","False"]'::jsonb, 1, 'Exchanging one crypto-asset for another is also a disposition that can create a gain or loss. Business-income or capital-gain rules depend on the facts.', 'lesson-module-7', 'medium', true),
  ('q-myth-9', 'employment-and-gig-income', 'A Canadian tax resident can ignore YouTube business revenue paid in US dollars.', '["True","False"]'::jsonb, 1, 'Canadian tax residents generally report worldwide income. Convert foreign-currency amounts into Canadian dollars using an appropriate exchange rate.', 'lesson-module-7', 'medium', true),
  ('q-myth-10', 'slips-and-documents', 'If your employer has not sent a T4, you have no employment income to report.', '["True","False"]'::jsonb, 1, 'Ask for the missing slip and check CRA My Account. If necessary, use records to estimate the income and deductions and correct the return when accurate information arrives.', 'lesson-module-11', 'medium', true),
  ('q-basics-1', 'tax-basics', 'Which government agency administers income taxes in Canada?', '["Canada Revenue Agency (CRA)","Service Canada","The Bank of Canada","Statistics Canada"]'::jsonb, 0, 'The CRA collects taxes and pays out most benefits and credits. (In Quebec, Revenu Québec also handles the provincial return.)', 'lesson-tax-basics-what-are-taxes', null, true),
  ('q-basics-2', 'tax-basics', 'What do you need before you can file a Canadian tax return?', '["A passport","A Social Insurance Number (SIN)","A driver''s licence","A credit card"]'::jsonb, 1, 'Your SIN is the number the CRA uses to identify you. You can''t file without one.', 'lesson-tax-basics-what-are-taxes', null, true),
  ('q-basics-3', 'tax-basics', 'Should you file a tax return even if you earned little or no income?', '["No, it''s a waste of time","Only if you owe money","Yes — filing is how you get benefits and credits","Only after you turn 25"]'::jsonb, 2, 'Filing is required to keep receiving benefit and credit payments you''re entitled to — even with $0 income.', 'guide-do-i-need-to-file', null, true),
  ('q-basics-4', 'tax-basics', 'A tax refund happens when…', '["The government gives everyone free money","You paid more tax during the year than you actually owed","You skip filing","You earn over $100,000"]'::jsonb, 1, 'A refund is your own overpaid tax coming back to you — for example, if too much was taken off your paycheques.', 'lesson-tax-basics-what-are-taxes', null, true),
  ('q-basics-5', 'tax-basics', 'You drive for a food-delivery app on weekends. Do you have to report that income?', '["No, gig work is tax-free","Only if they mail you a slip","Yes — all income must be reported, even without a slip","Only if you make over $30,000"]'::jsonb, 2, 'Tips, gig work and self-employed earnings must all be reported, even when no slip is issued.', 'lesson-gig-income', null, true),
  ('q-slips-1', 'slips-and-documents', 'Which slip shows the employment income you earned at a job?', '["T4","T5","T2202","T4A"]'::jsonb, 0, 'A T4 reports your employment income and the tax already withheld by your employer.', 'guide-what-is-a-t4', null, true),
  ('q-slips-2', 'slips-and-documents', 'Which slip commonly reports scholarships, bursaries, or certain self-employment or pension income?', '["T4","T5","T4A","T1"]'::jsonb, 2, 'A T4A covers income like scholarships, RESP payments, pensions, and some self-employment fees.', 'lesson-slips-overview', null, true),
  ('q-slips-3', 'slips-and-documents', 'Which slip reports interest income, such as interest from a savings account?', '["T2202","T5","T4","T4A"]'::jsonb, 1, 'A T5 reports investment income like interest and dividends.', 'lesson-slips-overview', null, true),
  ('q-slips-4', 'slips-and-documents', 'As a post-secondary student, which certificate reports your eligible tuition?', '["T4","T2202","T5","T1 General"]'::jsonb, 1, 'The T2202 shows eligible tuition and months of study. You can claim it or carry it forward.', 'lesson-slips-overview', null, true),
  ('q-slips-5', 'slips-and-documents', 'If you paid tuition as a student, that amount can generally be…', '["Ignored on your taxes","Claimed on your return, or carried forward/transferred","Only used for a loan","Turned into cash immediately"]'::jsonb, 1, 'Tuition credits can lower your tax, be carried forward to a future year, or (in some cases) transferred to a parent or grandparent.', 'lesson-slips-overview', null, true),
  ('q-slips-6', 'slips-and-documents', 'What is a TD1 form for?', '["Reporting your tips to the CRA","Telling your employer how much tax to take off your pay","Claiming a refund directly","Opening a TFSA"]'::jsonb, 1, 'You fill in a TD1 when you start a job. It sets how much tax your employer withholds from each paycheque.', 'lesson-td1', null, true),
  ('q-pay-1', 'your-paycheque', 'What is the difference between gross pay and net pay?', '["They are the same thing","Gross is what you earn; net is what actually reaches your account","Net is before deductions; gross is after","Gross applies only to salaried jobs"]'::jsonb, 1, 'Gross pay is your full earnings. Net (take-home) pay is what lands in your bank after deductions.', 'lesson-paycheque-gross-vs-net', null, true),
  ('q-pay-2', 'your-paycheque', 'What does CPP stand for on your pay stub?', '["Canada Payroll Plan","Canada Pension Plan","Certified Payment Program","Consumer Price Protection"]'::jsonb, 1, 'CPP is the Canada Pension Plan — money set aside toward income when you retire.', 'lesson-paycheque-gross-vs-net', null, true),
  ('q-pay-3', 'your-paycheque', 'What is EI for?', '["Extra investment income","Support if you lose your job","Employer insurance for workplace tools","A savings account bonus"]'::jsonb, 1, 'EI is Employment Insurance. It can provide some income if you lose your job.', 'lesson-paycheque-gross-vs-net', null, true),
  ('q-pay-4', 'your-paycheque', 'Your first paycheque is smaller than hours × wage. The most likely reason is…', '["Your employer made an error","Income tax, CPP and EI were deducted","The bank took a fee","You were paid for fewer hours on purpose"]'::jsonb, 1, 'Payroll deductions — income tax, CPP and EI — are normal and explain the gap. It is not an employer mistake.', 'lesson-paycheque-gross-vs-net', null, true),
  ('q-dead-1', 'deadlines-and-penalties', 'What''s the general deadline to file your personal tax return and pay any balance owing?', '["December 31","April 30","January 1","June 30"]'::jsonb, 1, 'For most people the filing and payment deadline is April 30. Dates shift if that falls on a weekend — check canada.ca.', 'lesson-deadlines', null, true),
  ('q-dead-2', 'deadlines-and-penalties', 'If you (or your spouse) are self-employed, your filing deadline is…', '["April 30","June 15 (but any tax owing is still due April 30)","December 31","There''s no deadline"]'::jsonb, 1, 'Self-employed people have until June 15 to file, but any balance owing is still due by April 30.', 'lesson-deadlines', null, true),
  ('q-dead-3', 'deadlines-and-penalties', 'What is the CRA''s late-filing penalty if you owe money and file late?', '["A flat $50","Nothing, ever","5% of the balance owing, plus 1% for each full month late","Half of your refund"]'::jsonb, 2, 'The penalty is 5% of your balance owing plus 1% for each full month your return is late (up to 12 months). Verify current rules on canada.ca.', 'lesson-deadlines', null, true),
  ('q-dead-4', 'deadlines-and-penalties', 'The CRA service that lets you file your return online through certified software is called…', '["e-Transfer","NETFILE","AutoPay","MyCRA Wallet"]'::jsonb, 1, 'NETFILE sends your return to the CRA using certified tax software — the fastest way to file.', 'lesson-deadlines', null, true),
  ('q-dead-5', 'deadlines-and-penalties', 'When you file electronically, refunds are typically issued in about…', '["2 weeks","6 months","1 day","1 year"]'::jsonb, 0, 'Filing online with direct deposit usually gets your refund to you in around two weeks.', 'lesson-deadlines', null, true),
  ('q-dead-6', 'deadlines-and-penalties', 'If you cannot pay what you owe by the deadline, you should…', '["Skip filing until you can pay","File on time anyway, then deal with the balance","Wait for the CRA to contact you","File next year instead"]'::jsonb, 1, 'Always file on time even if you cannot pay. The late-filing penalty is charged on top of interest, so filing late costs more.', 'lesson-deadlines', null, true),
  ('q-ben-1', 'credits-and-benefits', 'To qualify for the CGEB (formerly GST/HST credit) on your own, you generally must be at least…', '["16","18","19","25"]'::jsonb, 2, 'You generally need to be 19 or older to get the CGEB (formerly GST/HST credit) on your own (younger people can qualify if they are a parent or have a spouse/partner).', 'lesson-credits-benefits', null, true),
  ('q-ben-2', 'credits-and-benefits', 'How do you receive the CGEB (formerly GST/HST credit) and related benefits?', '["Apply at a bank","By filing your tax return — it''s assessed automatically","Call your employer","You can''t get it under 30"]'::jsonb, 1, 'Just file your return. The CRA works out your eligibility automatically from it.', 'lesson-credits-benefits', null, true),
  ('q-ben-3', 'credits-and-benefits', 'Is the CGEB (formerly GST/HST credit) considered taxable income?', '["Yes, you pay tax on it","No — it''s tax-free","Only half of it","Only if you''re employed"]'::jsonb, 1, 'The CGEB (formerly GST/HST credit) is a tax-free payment meant to offset sales tax for lower-income people.', 'lesson-credits-benefits', null, true),
  ('q-ben-4', 'credits-and-benefits', 'Filing your taxes matters mainly because…', '["It''s fun","Your benefit and credit payments are calculated from your return","It raises your credit score","It cancels your student loans"]'::jsonb, 1, 'Payments like the CGEB (formerly GST/HST credit) and Canada Child Benefit are based on the info in your return — no return, no payments.', 'lesson-credits-benefits', null, true),
  ('q-ben-5', 'credits-and-benefits', 'Where can people with modest income and a simple tax situation get free help filing?', '["Nowhere — it always costs money","CRA free volunteer tax clinics (CVITP)","Only from a bank","Only from a lawyer"]'::jsonb, 1, 'Free volunteer tax clinics help people with modest incomes and simple returns file at no cost.', 'lesson-deadlines', null, true),
  ('q-ben-6', 'credits-and-benefits', 'What is the difference between a deduction and a credit?', '["They are the same","A deduction lowers taxable income; a credit lowers the tax itself","A credit lowers income; a deduction lowers tax","Only businesses get deductions"]'::jsonb, 1, 'Deductions come off your income before tax is calculated. Credits reduce the tax amount after it is calculated.', 'guide-deductions-vs-credits', null, true),
  ('q-save-1', 'tfsa-and-rrsp', 'What''s the minimum age to open a TFSA (Tax-Free Savings Account)?', '["16","18","21","25"]'::jsonb, 1, 'You can open a TFSA once you are 18 and have a valid SIN (some provinces require 19 to enter the contract, but room starts building at 18).', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-save-2', 'tfsa-and-rrsp', 'Are withdrawals from a TFSA taxed?', '["Yes, like regular income","No — TFSA withdrawals are tax-free","Only if over $1,000","Only before age 65"]'::jsonb, 1, 'Money you take out of a TFSA is tax-free and doesn''t affect your federal benefits.', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-save-3', 'tfsa-and-rrsp', 'Are contributions to a TFSA tax-deductible?', '["Yes, they lower your taxable income","No — TFSA contributions are not tax-deductible","Only the first $1,000","Only for students"]'::jsonb, 1, 'Unlike an RRSP, TFSA contributions do NOT reduce your taxable income — the perk is tax-free growth and withdrawals.', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-save-4', 'tfsa-and-rrsp', 'After you withdraw money from a TFSA, your contribution room…', '["Is gone forever","Comes back the following calendar year","Doubles instantly","Only returns at age 71"]'::jsonb, 1, 'Withdrawn amounts are added back to your contribution room, but not until the next calendar year.', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-save-5', 'tfsa-and-rrsp', 'RRSP (Registered Retirement Savings Plan) contributions are…', '["Tax-deductible — they reduce your taxable income","Never useful","Taxed twice","Only for people over 60"]'::jsonb, 0, 'RRSP contributions are deductible, so they can lower the tax you owe for that year.', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-save-6', 'tfsa-and-rrsp', 'When you withdraw money from an RRSP (for example, in retirement), it is…', '["Tax-free","Taxed as income","Illegal","Matched by the government"]'::jsonb, 1, 'RRSP withdrawals are taxed as income — you defer the tax until you take the money out, ideally when your income is lower.', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-save-7', 'tfsa-and-rrsp', 'Which account gives you an immediate tax deduction when you contribute?', '["TFSA","RRSP","A chequing account","Neither"]'::jsonb, 1, 'The RRSP gives an upfront deduction; the TFSA''s advantage is tax-free withdrawals later. Which is ''better'' depends on your situation.', 'lesson-tfsa-vs-rrsp', null, true),
  ('q-credit-1', 'banking-and-credit', 'If you pay only the minimum payment on a credit card each month…', '["The balance clears just as fast","Interest keeps building and the debt can stretch for years","Interest is waived","Your limit automatically increases"]'::jsonb, 1, 'The minimum keeps your account in good standing but not much more. Interest on the remaining balance can make a purchase cost far more.', 'lesson-credit-cards-interest', null, true),
  ('q-credit-2', 'banking-and-credit', 'What is a credit score used for?', '["Calculating your tax refund","Judging how reliably you repay borrowed money","Setting your hourly wage","Deciding your TFSA limit"]'::jsonb, 1, 'Lenders use your credit score to judge repayment reliability. On-time payments help it; missed payments and collections hurt it.', 'lesson-credit-cards-interest', null, true),
  ('q-credit-3', 'saving-and-investing', 'What is an emergency fund for?', '["Booking spontaneous trips","Covering surprise costs without borrowing at high interest","Paying your taxes early","Buying investments on margin"]'::jsonb, 1, 'A cushion turns an emergency into an inconvenience — you pay once instead of paying interest for months.', 'lesson-emergency-fund', null, true)
insert into public.content_videos (id, title, question, description, category, youtube_id, duration_seconds, transcript, captions_available, related_lesson_id, related_quiz_id, featured, xp, sort_order, published) values
  ('video-first-paycheque', 'Your first paycheque, decoded', 'You got your first job at $18/hour — how much are you actually taking home?', 'The classic first-paycheque shock. We break a real pay stub down from gross pay to the amount that actually lands in your account.', 'Your Paycheque', '', null, null, false, 'lesson-paycheque-gross-vs-net', 'quiz-your-paycheque', true, 10, 1, true),
  ('video-what-is-income-tax', 'What is income tax, really?', 'What is income tax, really?', 'What income tax is, who collects it (hello, CRA), and why a slice of what you earn goes to it.', 'Your Paycheque', '', null, null, false, 'lesson-tax-basics-what-are-taxes', 'quiz-tax-basics', false, 10, 2, true),
  ('video-what-is-cpp', 'What is CPP?', 'What is CPP, and why is it on my pay stub?', 'The Canada Pension Plan explained — what it is, why it is deducted, and what you get for it later.', 'Your Paycheque', '', null, null, false, 'lesson-paycheque-gross-vs-net', null, false, 10, 3, true),
  ('video-what-is-ei', 'What is EI?', 'What is EI?', 'Employment Insurance in plain terms: what the deduction is for and when it can help you.', 'Your Paycheque', '', null, null, false, 'lesson-paycheque-gross-vs-net', null, false, 10, 4, true),
  ('video-why-pay-smaller', 'Why is my paycheque smaller than I expected?', 'Why is my paycheque smaller than I expected?', 'We add up every deduction — tax, CPP, EI — so the gap between your hourly rate and your take-home finally makes sense.', 'Your Paycheque', '', null, null, false, 'lesson-paycheque-gross-vs-net', 'quiz-your-paycheque', false, 10, 5, true),
  ('video-what-is-a-t4', 'What is a T4?', 'What is a T4?', 'The slip your employer gives you at tax time, what is on it, and why you need it to file.', 'Forms & Slips', '', null, null, false, 'guide-what-is-a-t4', 'quiz-slips', false, 10, 6, true),
  ('video-what-is-td1', 'What is a TD1 form?', 'What is a TD1 form, and why does my employer want it?', 'The form you fill out when you are hired — and how getting it right affects how much tax comes off your pay.', 'Forms & Slips', '', null, null, false, 'lesson-td1', 'quiz-slips', false, 10, 7, true),
  ('video-tax-brackets', 'How do tax brackets actually work?', 'How do tax brackets actually work?', 'The biggest tax myth, busted: moving into a higher bracket does NOT mean every dollar you earn is taxed more.', 'Filing', '', null, null, false, 'guide-tax-brackets', 'quiz-tax-basics', true, 15, 8, true),
  ('video-when-must-i-file', 'When do I have to file a tax return?', 'When do I have to file a tax return?', 'Who needs to file, the April 30 deadline, and why filing is worth it even when you do not owe.', 'Filing', '', null, null, false, 'guide-file-first-return', 'quiz-deadlines', false, 15, 9, true),
  ('video-what-if-i-dont-file', 'What happens if I don''t file?', 'What happens if I don''t file?', 'Late penalties, lost benefits, and how a missed return can quietly cost you money.', 'Filing', '', null, null, false, 'lesson-deadlines', 'quiz-deadlines', false, 15, 10, true),
  ('video-what-is-a-refund', 'What is a tax refund?', 'What is a tax refund?', 'Why a refund isn''t free money — it''s your own overpaid tax coming back to you.', 'Filing', '', null, null, false, 'lesson-tax-basics-what-are-taxes', 'quiz-tax-basics', false, 10, 11, true),
  ('video-tfsa-vs-rrsp', 'TFSA vs RRSP', 'TFSA vs RRSP — what''s the difference?', 'Two accounts, opposite superpowers. Which one makes sense when you are just starting out.', 'Saving & Growing', '', null, null, false, 'lesson-tfsa-vs-rrsp', 'quiz-saving', true, 15, 12, true),
  ('video-how-gst-hst-works', 'How does GST/HST work?', 'How does GST/HST work?', 'The sales tax you pay on almost everything — and the tax-free credit that can put some of it back in your pocket.', 'Everyday Money', '', null, null, false, 'lesson-credits-benefits', 'quiz-benefits', false, 15, 13, true),
  ('video-moving-out', 'Moving out and taxes', 'What happens (tax-wise) when I move out?', 'Independence and taxes: what changes on your return once you are on your own.', 'Life Events', '', null, null, false, 'lesson-tax-basics-what-are-taxes', null, false, 10, 14, true),
  ('video-going-freelance', 'Going freelance or self-employed', 'Going freelance or self-employed — what changes?', 'No employer taking tax off for you: what you now track, save for, and can deduct.', 'Life Events', '', null, null, false, 'lesson-gig-income', 'quiz-tax-basics', false, 15, 15, true)
insert into public.content_glossary (term, definition, category_id) values
  ('CRA', 'The Canada Revenue Agency, the group in charge of taxes in Canada. It collects taxes and pays out most benefits and credits.', 'tax-basics'),
  ('SIN', 'Social Insurance Number, the personal number you need to file taxes and to open accounts like a TFSA.', 'tax-basics'),
  ('Gross pay', 'The full amount you earn before anything is taken off.', 'your-paycheque'),
  ('Net pay', 'Your take home pay — the amount that actually reaches your bank account after deductions.', 'your-paycheque'),
  ('CPP', 'The Canada Pension Plan, savings toward income for when you retire.', 'your-paycheque'),
  ('EI', 'Employment Insurance, support if you lose your job.', 'your-paycheque'),
  ('NETFILE', 'The CRA service for filing your taxes online through certified software.', 'deadlines-and-penalties'),
  ('Refund', 'Money you get back when too much tax was taken off during the year.', 'tax-basics'),
  ('CGEB (formerly GST/HST credit)', 'A tax free payment that helps lower income people with sales tax.', 'credits-and-benefits'),
  ('TFSA', 'Tax Free Savings Account. Money grows and comes out tax free, but contributions are not deductible.', 'tfsa-and-rrsp'),
  ('RRSP', 'Registered Retirement Savings Plan. Contributions lower your tax now, and withdrawals are taxed later.', 'tfsa-and-rrsp'),
  ('T4', 'The slip showing money you earned from a job and the tax already taken off.', 'slips-and-documents'),
  ('T4A', 'A slip covering other income like scholarships, and some self employed or pension income.', 'slips-and-documents'),
  ('T5', 'A slip showing interest or investment income, such as from a savings account.', 'slips-and-documents'),
  ('T2202', 'A certificate showing the tuition you paid as a post-secondary student.', 'slips-and-documents'),
  ('TD1', 'The form you fill in when you start a job. It tells your employer how much tax to take off your pay.', 'slips-and-documents'),
  ('Deduction', 'An amount that comes off your income before tax is calculated.', 'credits-and-benefits'),
  ('Credit', 'An amount that reduces the tax you owe after it has been calculated.', 'credits-and-benefits'),
  ('Tax bracket', 'A slice of income taxed at its own rate. Only the dollars inside a higher bracket are taxed at that higher rate.', 'tax-basics'),
  ('Emergency fund', 'Savings kept aside for surprise costs, so an emergency does not become high interest debt.', 'saving-and-investing')
insert into public.content_faqs (id, question, answer, sort_order, published) values
  ('faq-what-is', 'What is TaxIntuitive?', 'TaxIntuitive is a youth-focused financial-literacy project that makes taxes and personal finance easy to understand. We use trivia, expert videos, a money simulator, and plain-language guides so young people can learn how taxes actually work.', 1, true),
  ('faq-who-for', 'Who is this for?', 'Mainly high-school and college students and young adults in Canada — especially anyone about to get their first job or file their first tax return. That said, everyone is welcome; the basics are useful at any age.', 2, true),
  ('faq-free', 'Is TaxIntuitive free to use?', 'Yes. All of our learning tools — quizzes, videos, the simulator, and guides — are free to use.', 3, true),
  ('faq-account', 'Do I need an account?', 'No, not for the main app. You can read lessons, watch videos, take quizzes, use the simulator and earn XP as a guest, with your progress saved on your device. An account is only needed for Quiz Duo, inviting friends, leaderboards, and syncing your progress across devices.', 4, true),
  ('faq-offline', 'Does the app work offline?', 'Mostly yes. Lessons, guides, solo quizzes, the glossary, the simulator and FAQs all work offline once content has been downloaded, and your progress is stored locally. Quiz Duo needs an internet connection because it matches you with another player in real time.', 5, true),
  ('faq-advice', 'Is anything here official tax advice?', 'No. Everything on TaxIntuitive is for learning only and reflects general Canadian (CRA) rules, which can change. For your specific situation or the latest details, always check canada.ca or talk to a qualified professional.', 6, true),
  ('faq-canadian', 'Is the tax info Canadian or American?', 'Canadian. Our content is based on the Canada Revenue Agency (CRA) and Canadian rules — things like T4s, TFSAs, RRSPs, and the CGEB (formerly GST/HST credit).', 7, true),
  ('faq-updates', 'How often is the content updated?', 'We review our content regularly and update it as tax rules and amounts change each year. Every tax lesson shows when it was last reviewed and links to its official source. When in doubt, canada.ca always has the most current figures.', 8, true),
  ('faq-school', 'Can my school or class use TaxIntuitive?', 'Absolutely — that''s a big part of why it exists. Teachers and student groups are welcome to use our tools, and we''re open to running workshops. Use the Workshops screen to request one.', 9, true),
  ('faq-suggest', 'How can I suggest a topic or ask a tax question?', 'We''d love that. Email us at jackyluan777@gmail.com — your question might even become the next expert video.', 10, true)
insert into public.content_simulator_scenarios (id, month_label, prompt, category_id, options, sort_order, published) values
  ('sim-td1', 'Month 1 — Getting hired', 'Your new employer hands you a TD1 form to fill out before your first shift. What do you do?', 'slips-and-documents', '[{"id":"sim-td1-careful","label":"Fill it out carefully — it sets how much tax comes off your pay","cashDelta":0,"smartsDelta":15,"feedback":"Smart. The TD1 tells your employer how much tax to withhold. Getting it right means fewer surprises at tax time.","lesson":"A TD1 form controls how much tax is taken off each paycheque."},{"id":"sim-td1-rush","label":"Scribble anything so you can start working","cashDelta":0,"smartsDelta":0,"feedback":"It won''t ruin you, but a careless TD1 can mean too much (or too little) tax withheld. Worth two minutes to do right.","lesson":"Rushing your TD1 can throw off your paycheque withholding."}]'::jsonb, 1, true),
  ('sim-first-pay', 'Month 2 — First paycheque', 'You worked at $20/hr but your first paycheque is smaller than you expected. Your reaction?', 'your-paycheque', '[{"id":"sim-first-pay-check","label":"Check the pay stub — taxes, CPP and EI are deducted","cashDelta":1000,"incomeDelta":1000,"smartsDelta":15,"feedback":"Exactly. Gross pay minus income tax, CPP and EI = your take-home. Now that gap makes sense. (+$1,000 banked.)","lesson":"Take-home pay = gross pay minus tax, CPP and EI."},{"id":"sim-first-pay-complain","label":"Assume your boss made an error and complain","cashDelta":1000,"incomeDelta":1000,"smartsDelta":0,"feedback":"The math is right — those are normal payroll deductions, not a mistake. Still got paid though. (+$1,000 banked.)","lesson":"Payroll deductions are normal, not an employer error."}]'::jsonb, 2, true),
  ('sim-banking', 'Month 3 — Setting up money', 'Your pay is landing in one chequing account and disappearing. How do you organize it?', 'banking-and-credit', '[{"id":"sim-banking-auto","label":"Set up direct deposit plus an automatic transfer to savings each payday","cashDelta":0,"savingsDelta":200,"smartsDelta":15,"feedback":"This is the single highest-leverage money habit. Saving automatically means you never have to rely on willpower. ($200 moved to savings.)","lesson":"Automatic transfers on payday build savings without willpower."},{"id":"sim-banking-manual","label":"Keep it all in chequing and save whatever''s left at month end","cashDelta":0,"smartsDelta":5,"feedback":"Nothing is usually left at month end — that''s how it goes for most people. Paying yourself first works better.","lesson":"Saving \"what is left over\" usually means saving nothing."}]'::jsonb, 3, true),
  ('sim-car-repair', 'Month 4 — A surprise bill', 'Your car needs a $1,200 repair to get to work. How do you handle it?', 'saving-and-investing', '[{"id":"sim-car-savings","label":"Pay from savings — this is what an emergency fund is for","cashDelta":-1200,"smartsDelta":15,"feedback":"Ouch, but exactly right. Paying cash avoids interest. This is why a cushion matters.","lesson":"An emergency fund saves you from borrowing at high interest."},{"id":"sim-car-credit","label":"Put it on a credit card and pay the minimum","cashDelta":-1200,"debtDelta":1200,"smartsDelta":5,"feedback":"You covered it, but carrying that balance adds interest — you''ll pay well over $1,200 in the end.","lesson":"Credit card interest makes borrowed money cost much more."}]'::jsonb, 4, true),
  ('sim-tax-season', 'Month 6 — Tax season', 'It''s your first tax season. Filing a return feels like a hassle. Do you file?', 'first-tax-return', '[{"id":"sim-file-yes","label":"File it — even with a small income","cashDelta":900,"smartsDelta":20,"feedback":"Great call. Filing triggered a refund of over-withheld tax AND signed you up for the GST/HST credit. (+$900 in refund and credits.)","lesson":"Filing unlocks refunds and benefits like the GST/HST credit."},{"id":"sim-file-no","label":"Skip it — you didn''t make much","cashDelta":0,"smartsDelta":0,"feedback":"By skipping, you left refund money unclaimed and missed benefit payments you qualified for. File next time!","lesson":"Not filing means missing refunds and benefit payments."}]'::jsonb, 5, true),
  ('sim-windfall', 'Month 7 — Found money', 'A GST/HST credit payment of $500 lands in your account. What now?', 'tfsa-and-rrsp', '[{"id":"sim-windfall-tfsa","label":"Move it into a TFSA so it can grow tax-free","cashDelta":500,"savingsDelta":500,"smartsDelta":15,"feedback":"Nice. In a TFSA your money grows and comes back out tax-free — perfect for building a cushion.","lesson":"A TFSA lets savings grow and be withdrawn tax-free."},{"id":"sim-windfall-spend","label":"Treat yourself — spend it all","cashDelta":500,"expenseDelta":500,"smartsDelta":0,"feedback":"You earned a little fun, but that was a chance to build savings. Balance is key.","lesson":"Windfalls are a chance to build savings, not just spend."}]'::jsonb, 6, true),
  ('sim-side-gig', 'Month 8 — A side gig', 'You start doing freelance graphic design on weekends. No employer is taking tax off. What is your move?', 'employment-and-gig-income', '[{"id":"sim-gig-setaside","label":"Set aside a share of each payment for taxes","cashDelta":800,"incomeDelta":800,"estimatedTaxDelta":200,"smartsDelta":20,"feedback":"Pro move. When you are self-employed, no tax is withheld — so you save for it yourself to avoid a shock. (+$800 earned, tax set aside.)","lesson":"Self-employed income has no tax withheld — set some aside yourself."},{"id":"sim-gig-spend","label":"Spend it all — it''s extra money","cashDelta":1000,"incomeDelta":1000,"estimatedTaxDelta":250,"smartsDelta":0,"feedback":"Fun now, but come tax time you may owe on this income with nothing set aside. (+$1,000 spent freely — watch out next April.)","lesson":"Spending all freelance income can leave you owing tax later."}]'::jsonb, 7, true),
  ('sim-peer-pressure', 'Month 9 — Peer pressure', 'Friends want to book a spontaneous trip. You''d have to max out your credit card to go. Do you?', 'banking-and-credit', '[{"id":"sim-trip-skip","label":"Skip it or save up first","cashDelta":0,"smartsDelta":15,"feedback":"Discipline pays. Maxing a card for wants is how debt snowballs. You can travel once you have saved.","lesson":"Borrowing for wants is how credit-card debt snowballs."},{"id":"sim-trip-max","label":"Max the card — you only live once","cashDelta":-900,"debtDelta":900,"smartsDelta":0,"feedback":"The memories are real, but so is the balance. High-interest debt now limits your choices later.","lesson":"High-interest debt limits your future choices."}]'::jsonb, 8, true),
  ('sim-education', 'Month 10 — Back to school', 'You enroll in a college course and pay tuition. The school sends you a T2202. What do you do with it?', 'slips-and-documents', '[{"id":"sim-edu-claim","label":"Keep it and use it on your return (or carry it forward)","cashDelta":0,"smartsDelta":15,"feedback":"Right. Tuition can lower your tax now, be carried forward to a year when it helps more, or sometimes be transferred to a parent.","lesson":"A T2202 can be claimed, carried forward, or transferred."},{"id":"sim-edu-toss","label":"Toss it — it looks like junk mail","cashDelta":0,"smartsDelta":0,"feedback":"That slip was worth money at tax time. Keep every slip you receive, even the ones that look boring.","lesson":"Keep every tax slip — some are worth money at filing time."}]'::jsonb, 9, true),
  ('sim-bad-luck', 'Month 11 — Bad luck', 'An unexpected dental bill of $600 hits. How are you set up to handle it?', 'saving-and-investing', '[{"id":"sim-dental-savings","label":"Cover it from your savings cushion","cashDelta":-600,"smartsDelta":10,"feedback":"This is exactly why you kept a cushion. No debt, no drama.","lesson":"A savings cushion turns emergencies into inconveniences."},{"id":"sim-dental-ignore","label":"Ignore it and hope it goes away","cashDelta":-750,"debtDelta":150,"smartsDelta":0,"feedback":"Unpaid bills can grow with fees or go to collections, hurting your credit. Better to plan for surprises.","lesson":"Ignoring bills can add fees and damage your credit."}]'::jsonb, 10, true),
  ('sim-year-end', 'Month 12 — Year-end', 'You''ve got some money left over as the year closes. What do you do with it?', 'tfsa-and-rrsp', '[{"id":"sim-yearend-invest","label":"Keep an emergency fund and invest the rest in a TFSA","cashDelta":300,"savingsDelta":300,"smartsDelta":20,"feedback":"Textbook. A cushion for surprises plus tax-free growth is a strong foundation for year two. (+$300 growth.)","lesson":"Keep an emergency fund, then invest the rest to grow."},{"id":"sim-yearend-idle","label":"Leave it all sitting in chequing","cashDelta":0,"smartsDelta":5,"feedback":"Safe, but idle cash doesn''t grow. Even a TFSA savings account would earn a little tax-free.","lesson":"Idle cash does not grow — put savings where they earn."}]'::jsonb, 11, true)
