  ('ach-simulator-gold', 'Money Smart', 'Reach a Gold result in the Tax Simulator.', '🥇', 'gold', '{"kind":"simulator_tier","tier":"gold"}'::jsonb, 8),
  ('ach-streak-3', 'Three in a Row', 'Learn something three days in a row.', '🔥', 'bronze', '{"kind":"streak_days","days":3}'::jsonb, 9),
  ('ach-streak-7', 'Week Strong', 'Keep a seven-day learning streak.', '⚡', 'silver', '{"kind":"streak_days","days":7}'::jsonb, 10),
  ('ach-xp-500', 'Halfway Hero', 'Earn 500 XP.', '🏅', 'silver', '{"kind":"total_xp","amount":500}'::jsonb, 11),
  ('ach-xp-1250', 'Financially Literate', 'Earn 1,250 XP.', '⭐', 'gold', '{"kind":"total_xp","amount":1250}'::jsonb, 12),
  ('ach-duo-first-win', 'Duo Debut', 'Win your first Quiz Duo match.', '🤝', 'bronze', '{"kind":"duo_wins","count":1}'::jsonb, 13),
  ('ach-duo-five-wins', 'Duo Champion', 'Win five Quiz Duo matches.', '👑', 'gold', '{"kind":"duo_wins","count":5}'::jsonb, 14),
  ('ach-quiz-ten', 'Quiz Machine', 'Pass ten quizzes.', '🚀', 'gold', '{"kind":"quizzes_passed","count":10}'::jsonb, 15)
